def _sdk_install_id() -> str:
    """Anonymous per-install id for SDK telemetry — its own id file, distinct
    from the harness CLI's install id, so SDK users are counted separately.
    Only ever leaves the machine when the harness has an OTLP endpoint
    configured (OTEL_EXPORTER_OTLP_ENDPOINT); opt out entirely with
    GRAFF_NO_TELEMETRY=1 or by passing --no-telemetry in `args`."""
    path = os.path.join(os.path.expanduser("~"), ".simple-harness-sdk-id")
    try:
        with open(path) as f:
            v = f.read().strip()
        if len(v) == 32 and all(c in "0123456789abcdef" for c in v):
            return v
    except OSError:
        pass
    v = secrets.token_hex(16)
    try:
        with open(path, "w") as f:
            f.write(v + "\n")
    except OSError:
        pass
    return v


def _default_binary() -> str:
    """The CLI is `graff` (renamed from `harness`); prefer it when on PATH,
    fall back to the old name so pre-rename installs keep working."""
    import shutil
    return "graff" if shutil.which("graff") else "harness"


_TELEMETRY_DEFAULT = "https://harness-telemetry.rachpradhan.workers.dev"


def _report_error(kind: str, detail: str) -> None:
    """Best-effort OTLP ERROR log for failures the harness process cannot
    report itself (it may be dead or never have started): spawn failures,
    mid-turn exits, protocol breaks. Same pipeline and opt-out as harness
    telemetry — skipped when GRAFF_NO_TELEMETRY is set; endpoint from
    OTEL_EXPORTER_OTLP_ENDPOINT / GRAFF_OTEL_ENDPOINT, else the default
    collector. Fire-and-forget on a daemon thread; never raises."""
    if os.environ.get("GRAFF_NO_TELEMETRY"):
        return
    base = (os.environ.get("OTEL_EXPORTER_OTLP_ENDPOINT")
            or os.environ.get("GRAFF_OTEL_ENDPOINT")
            or _TELEMETRY_DEFAULT).rstrip("/")
    url = base if base.endswith("/v1/logs") else base + "/v1/logs"
    payload = json.dumps({"resourceLogs": [{
        "resource": {"attributes": [
            {"key": "service.name", "value": {"stringValue": "simple-harness"}},
            {"key": "client.name", "value": {"stringValue": os.environ.get("HARNESS_CLIENT", "sdk-py")}},
            {"key": "sdk.install.id", "value": {"stringValue": _sdk_install_id()}},
        ]},
        "scopeLogs": [{"scope": {"name": "simple-harness-sdk"}, "logRecords": [{
            "timeUnixNano": str(int(time.time() * 1e9)),
            "severityText": "ERROR",
            "body": {"stringValue": "error"},
            "attributes": [
                {"key": "kind", "value": {"stringValue": kind}},
                {"key": "detail", "value": {"stringValue": detail[:512]}},
            ],
        }]}],
    }]}).encode()

    def post():
        try:
            req = urllib.request.Request(
                url, data=payload, headers={
                    "Content-Type": "application/json",
                    # urllib's default Python-urllib/x.y UA is bot-blocked by
                    # Cloudflare in front of the collector (403) — identify.
                    "User-Agent": "simple-harness-sdk-py",
                })
            urllib.request.urlopen(req, timeout=3).read()
        except Exception:
            pass
    threading.Thread(target=post, daemon=True).start()


def _fleet_signal(kind: str, attrs: Optional[dict] = None) -> None:
    """Prompt-free SDK fleet signal; local is the fail-closed default."""
    if os.environ.get("GRAFF_NO_TELEMETRY"):
        return
    privacy = os.environ.get("GRAFF_LEARNING_PRIVACY", "local")
    if privacy not in ("aggregate", "templates", "examples"):
        return
    attrs = {k: v for k, v in (attrs or {}).items() if k != "prompt_text"}
    base = (os.environ.get("OTEL_EXPORTER_OTLP_ENDPOINT")
            or os.environ.get("GRAFF_OTEL_ENDPOINT")
            or _TELEMETRY_DEFAULT).rstrip("/")
    url = base if base.endswith("/v1/logs") else base + "/v1/logs"
    al = [{"key": "kind", "value": {"stringValue": kind}}]
    for k, v in attrs.items():
        val = {"doubleValue": v} if isinstance(v, (int, float)) else {"stringValue": str(v)}
        al.append({"key": k, "value": val})
    payload = json.dumps({"resourceLogs": [{
        "resource": {"attributes": [
            {"key": "service.name", "value": {"stringValue": "simple-harness"}},
            {"key": "client.name", "value": {"stringValue": os.environ.get("HARNESS_CLIENT", "sdk-py")}},
            {"key": "sdk.install.id", "value": {"stringValue": _sdk_install_id()}},
        ]},
        "scopeLogs": [{"scope": {"name": "simple-harness-sdk"}, "logRecords": [{
            "timeUnixNano": str(int(time.time() * 1e9)),
            "body": {"stringValue": "fleet"},
            "attributes": al,
        }]}],
    }]}).encode()

    def post():
        try:
            req = urllib.request.Request(
                url, data=payload, headers={
                    "Content-Type": "application/json",
                    "User-Agent": "simple-harness-sdk-py",
                })
            urllib.request.urlopen(req, timeout=3).read()
        except Exception:
            pass
    threading.Thread(target=post, daemon=True).start()


def prompt_fingerprint(text: str) -> str:
    """Fingerprint of a system prompt as used in `.graff/trajectories` —
    the aggregate DGM-style archive — and by `Harness.score()`:
    first 8 bytes of SHA-256, hex (16 chars)."""
    return hashlib.sha256(text.encode()).hexdigest()[:16]


def score_signature(key: bytes, prompt_sha: str, parent_sha: str, score: float,
                    run_id: str, judge_id: str = "", artifact_sha: str = "",
                    eval_set_hash: str = "", niche: str = "",
                    provider_class: str = "") -> str:
    """Recompute a score record's HMAC the way the harness signs it (Step 0,
    fitness-channel integrity). The canonical v2 message is version-tagged and
    newline-joined with the score fixed to 6 decimals — byte-identical to the
    Zig signer (src/scoring.zig scoreSigMessage). v2 folds `niche` and
    `provider_class` into the signed envelope so a score for one MAP-Elites
    cell cannot be replayed into another. `score` is on the canonical [0, 1]
    scale. `key` is the raw bytes of the GRAFF_SCORE_KEY_FILE file."""
    msg = "v2\n{}\n{}\n{:.6f}\n{}\n{}\n{}\n{}\n{}\n{}".format(
        prompt_sha, parent_sha, score, run_id, judge_id, artifact_sha,
        eval_set_hash, niche, provider_class)
    return hmac.new(key, msg.encode(), hashlib.sha256).hexdigest()


def verify_score(key: bytes, rec: dict) -> bool:
    """True iff a kind:"score" trajectory/D1 record carries a valid signature
    for `key`. Use this in an evolution driver's archive loader to reject
    forged fitness rows (an attacker without the key cannot produce a matching
    sig). Verifies the v2 envelope first, then falls back to legacy v1 rows
    (signed before niche/provider_class entered the envelope — transition
    window only). Records with no sig fail closed when a key is set."""
    sig = rec.get("sig") or ""
    if not sig:
        return False
    # Run-scoped JSONL reserves top-level `run_id` for invocation identity.
    # Score provenance therefore uses `score_run_id`; legacy/D1 records still
    # carry the signed value as `run_id`.
    signed_run_id = rec.get("score_run_id", rec.get("run_id", ""))
    want = score_signature(
        key, rec.get("prompt_sha", ""), rec.get("parent_sha", "") or "",
        float(rec.get("score", "nan")), signed_run_id,
        rec.get("judge_id", ""), rec.get("artifact_sha", ""),
        rec.get("eval_set_hash", ""),
        # D1 returns NULL (None) for an empty niche/provider_class — "{}"
        # would format it as the literal "None" and poison the message.
        rec.get("niche", "") or "",
        rec.get("provider_class", "") or "")
    if hmac.compare_digest(sig, want):
        return True
    legacy = "v1\n{}\n{}\n{:.6f}\n{}\n{}\n{}\n{}".format(
        rec.get("prompt_sha", ""), rec.get("parent_sha", "") or "",
        float(rec.get("score", "nan")), signed_run_id,
        rec.get("judge_id", ""), rec.get("artifact_sha", ""),
        rec.get("eval_set_hash", ""))
    return hmac.compare_digest(
        sig, hmac.new(key, legacy.encode(), hashlib.sha256).hexdigest())

class Harness:
    """Drives a `harness --json` subprocess. One turn = send text, stream events.

    Events are plain dicts with a "type" field: "text", "tool_call",
    "ask_user", "tool_result", "turn", or "error" (see the harness
    --schema protocol).
    """

    def __init__(self, binary: Optional[str] = None, args: Optional[list] = None,
                 cwd: Optional[str] = None, env: Optional[dict] = None,
                 model: Optional[str] = None, yolo: bool = False,
                 system_prompt: Optional[str] = None,
                 append_system_prompt: Optional[str] = None,
                 max_tool_calls: Optional[int] = None,
                 dedupe_tool_calls: bool = False,
                 max_model_calls: Optional[int] = None,
                 compact_at: Optional[int] = None):
        binary = binary or _default_binary()
        argv = [binary, "--json"]
        if yolo:
            argv.append("--yolo")
        if model:
            argv += ["--model", model]
        if max_tool_calls is not None:
            argv += ["--max-tool-calls", str(max_tool_calls)]
        if max_model_calls is not None:
            argv += ["--max-model-calls", str(max_model_calls)]
        if dedupe_tool_calls:
            argv.append("--dedupe-tool-calls")
        if compact_at is not None:
            argv += ["--compact-at", str(compact_at)]
        if system_prompt:
            argv += ["--system-prompt", system_prompt]
        if append_system_prompt:
            argv += ["--append-system-prompt", append_system_prompt]
        argv += list(args or [])
        # Tag the harness child as SDK-driven for telemetry attribution
        # (explicit caller values win). The id file is only read/created when
        # telemetry is actually live — same gating as the harness CLI's own id.
        run_env = dict(env if env is not None else os.environ)
        run_env.setdefault("HARNESS_CLIENT", "sdk-py")
        live = not run_env.get("GRAFF_NO_TELEMETRY") and (
            run_env.get("OTEL_EXPORTER_OTLP_ENDPOINT") or run_env.get("GRAFF_OTEL_ENDPOINT"))
        if live and "HARNESS_SDK_INSTALL_ID" not in run_env:
            run_env["HARNESS_SDK_INSTALL_ID"] = _sdk_install_id()
        try:
            self.proc = subprocess.Popen(
                argv, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                text=True, bufsize=1, cwd=cwd, env=run_env,
            )
        except OSError as e:
            _report_error("spawn", f"{binary}: {e}")
            raise

    def chat(self, text: str, review: bool = False,
             images: Optional[List[ImageInput]] = None) -> Iterator[dict]:
        """Send a user turn; yield events until (and including) the 'turn'
        event. Raises RuntimeError (after reporting to telemetry) if the
        harness process dies mid-turn instead of silently yielding nothing."""
        assert self.proc.stdin and self.proc.stdout
        try:
            payload = {"type": "review" if review else "user", "text": text}
            if images:
                payload["images"] = images
            self.proc.stdin.write(json.dumps(payload) + "\n")
            self.proc.stdin.flush()
        except OSError as e:
            _report_error("died", f"harness pipe closed on send: {e}")
            raise
        for line in self.proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            yield ev
            if ev.get("type") in ("turn", "error"):
                return
        # stdout EOF without a terminal event: the harness died mid-turn.
        rc = self.proc.poll()
        _report_error("died", f"harness exited mid-turn (rc={rc})")
        raise RuntimeError(f"harness exited mid-turn (rc={rc})")

    def ask(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        """Run a turn and return just the final assistant text."""
        final = ""
        for ev in self.chat(text, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def review(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        """Run one isolated, read-only review turn and return its report."""
        final = ""
        for ev in self.chat(text, review=True, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def answer(self, text: str = "", cancelled: bool = False,
               call_id: Optional[str] = None) -> None:
        """Answer an in-flight ask_user event while chat() is being consumed."""
        assert self.proc.stdin
        req = {"type": "answer", "text": text, "cancelled": cancelled}
        if call_id:
            req["call_id"] = call_id
        self.proc.stdin.write(json.dumps(req) + "\n")
        self.proc.stdin.flush()

    def set_system_prompt(self, text: str, append: bool = False) -> None:
        """Replace (or with append=True, extend) the system prompt for later
        turns. Call between turns; blocks until the harness acks.

        KV-cache warning (Manus context-engineering lessons): the system
        prompt heads the cached prefix, so ANY mutation — append included —
        invalidates the cache for the whole conversation; the next turn
        re-reads everything at full input price. Prefer the spawn-time
        system_prompt/append_system_prompt arguments; mutate only at task
        boundaries, never back-and-forth inside a loop."""
        assert self.proc.stdin and self.proc.stdout
        self.proc.stdin.write(json.dumps(
            {"type": "set_system_prompt", "text": text, "append": append}) + "\n")
        self.proc.stdin.flush()
        for line in self.proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            if ev.get("type") == "error":
                raise RuntimeError(ev["message"])
            if ev.get("type") == "system_prompt":
                return
        _report_error("died", f"harness closed before acking set_system_prompt (rc={self.proc.poll()})")
        raise RuntimeError("harness closed before acking set_system_prompt")

    def append_system_prompt(self, text: str) -> None:
        """Tack extra instructions onto the current system prompt."""
        self.set_system_prompt(text, append=True)

    def score(self, prompt_or_sha: str, value: float, notes: str = "",
              parent: Optional[str] = None, judge_id: str = "",
              artifact_sha: str = "", eval_set_hash: str = "",
              niche: str = "", scale: str = "") -> None:
        """Record an evaluation score for an agent/prompt variant in the
        aggregate trajectory archive (`.graff/trajectories`) — the DGM evaluation
        phase writing back. `prompt_or_sha` is either the full system-prompt
        text (fingerprinted for you) or an existing 16-hex fingerprint.
        Pass `parent` (text or sha) when the variant was mutated from
        another prompt: that genome-lineage edge is what DGM parent
        selection counts children with.

        Provenance (signed when GRAFF_SCORE_KEY_FILE is set): `judge_id`
        names the evaluator, `artifact_sha` the thing it judged, and
        `eval_set_hash` the held-out eval used — all folded into the record's
        HMAC so a forged fitness row is detectable (see `verify_score`).
        `niche` (reviewer/researcher/implementer/skeptic, or a custom agent)
        files the score into that MAP-Elites cell so the fleet can promote a
        champion for the role; full text produces only a prompt-free fingerprint
        proposal until the SDK has an interactive review UI.

        Scale: the canonical wire scale is [0, 1]. Pass scale="unit" to
        assert `value` is already in [0, 1] (anything else is rejected), or
        scale="percent" to always send value/100 (accepts [0, 100] — note a
        percent-scale 0.5 means 0.005, not 0.5). Without `scale` the harness
        heuristic applies: [0, 1] passes as-is, values in (1, 100] are
        treated as percentages and normalized to /100, and values outside
        [0, 100] are rejected. Call between turns; blocks until the harness
        acks."""
        assert self.proc.stdin and self.proc.stdout
        sha = prompt_or_sha if re.fullmatch(r"[0-9a-f]{16}", prompt_or_sha) \
            else prompt_fingerprint(prompt_or_sha)
        req = {"type": "score", "prompt_sha": sha, "score": value, "notes": notes}
        if parent is not None:
            req["parent_sha"] = parent if re.fullmatch(r"[0-9a-f]{16}", parent) \
                else prompt_fingerprint(parent)
        if judge_id:
            req["judge_id"] = judge_id
        if artifact_sha:
            req["artifact_sha"] = artifact_sha
        if eval_set_hash:
            req["eval_set_hash"] = eval_set_hash
        if niche:
            req["niche"] = niche
        if scale:
            req["scale"] = scale
        # The SDK emitter strips prompt_text until it has an interactive review UI.
        if niche and not re.fullmatch(r"[0-9a-f]{16}", prompt_or_sha):
            _fleet_signal("propose", {"niche": niche, "prompt_sha": sha,
                                      "parent_sha": req.get("parent_sha", ""),
                                      "prompt_text": prompt_or_sha})
        self.proc.stdin.write(json.dumps(req) + "\n")
        self.proc.stdin.flush()
        for line in self.proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            if ev.get("type") == "error":
                raise RuntimeError(ev["message"])
            if ev.get("type") == "score":
                _fleet_signal("submit", {"prompt_sha": sha, "eval_set_hash": eval_set_hash, "niche": niche})
                return
        _report_error("died", f"harness closed before acking score (rc={self.proc.poll()})")
        raise RuntimeError("harness closed before acking score")

    def pull_elites(self, provider_class: str, eval_set_hash: str = "") -> list:
        """Pull fleet champions; local mode returns without network access."""
        if os.environ.get("GRAFF_LEARNING_PRIVACY", "local") not in ("aggregate", "templates", "examples"):
            return []
        base = (os.environ.get("OTEL_EXPORTER_OTLP_ENDPOINT")
                or os.environ.get("GRAFF_OTEL_ENDPOINT")
                or _TELEMETRY_DEFAULT).rstrip("/")
        if base.endswith("/v1/logs"):
            base = base[: -len("/v1/logs")]
        q = "provider_class=" + provider_class
        if eval_set_hash:
            q += "&eval_set_hash=" + eval_set_hash
        elites: list = []
        try:
            req = urllib.request.Request(
                base + "/v1/elites?" + q,
                headers={"User-Agent": "simple-harness-sdk-py"})
            body = urllib.request.urlopen(req, timeout=5).read()
            elites = (json.loads(body) or {}).get("elites", []) or []
        except Exception:
            pass
        _fleet_signal("elite_pull", {"provider_class": provider_class,
                                      "eval_set_hash": eval_set_hash,
                                      "n_elites": len(elites)})
        return elites
    def close(self):
        """Close stdin and give the harness a moment to exit cleanly — it
        flushes telemetry and trajectory records on the way out; killing it
        immediately would race (and lose) that flush."""
        if self.proc.stdin:
            self.proc.stdin.close()
        try:
            self.proc.wait(timeout=15)
        except subprocess.TimeoutExpired:
            self.proc.terminate()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()


class RemoteHarness:
    """Drives a session on a remote `harness serve` bridge over HTTP — the
    network-transport analogue of `Harness`, same method surface. The server
    side runs `harness serve` (see the "serve" key of `harness --schema`);
    each session is a real `harness --json` child over there, and one POST =
    one protocol request, streamed back as NDJSON until its terminal event.

    Stdlib-only (urllib): usable anywhere Python runs, no local binary
    needed. Pass yolo=True in most cases — the bridge has no terminal to
    show permission prompts on.

    #330: sessions are durable. Pass `session="<name>"` and the bridge runs
    `graff --json --resume <name>`, so a REPLACEMENT bridge given the same
    name continues the run. Every event carries a monotonic `seq`; after a
    dropped stream, `reconnect()` replays exactly what was missed."""

    def __init__(self, url: str, token: Optional[str] = None,
                 model: Optional[str] = None, yolo: bool = False,
                 system_prompt: Optional[str] = None,
                 append_system_prompt: Optional[str] = None,
                 max_tool_calls: Optional[int] = None,
                 dedupe_tool_calls: bool = False,
                 session_id: Optional[str] = None,
                 max_model_calls: Optional[int] = None,
                 session: Optional[str] = None):
        self.base = url.rstrip("/")
        self.token = token
        # #330: highest event seq seen. reconnect() picks up from last_seq + 1.
        self.last_seq = 0
        self.info = None
        if session_id is not None:
            self.session_id = session_id
            return
        opts = {}
        # A durable session name: the bridge runs the child as
        # `graff --json --resume <session>`, so a REPLACEMENT bridge given the
        # same name continues the run from its last persisted turn.
        if session:
            opts["session"] = session
        if model:
            opts["model"] = model
        if yolo:
            opts["yolo"] = True
        if system_prompt:
            opts["system_prompt"] = system_prompt
        if append_system_prompt:
            opts["append_system_prompt"] = append_system_prompt
        if max_tool_calls is not None:
            opts["maxToolCalls"] = max_tool_calls
        if max_model_calls is not None:
            opts["maxModelCalls"] = max_model_calls
        if dedupe_tool_calls:
            opts["dedupeToolCalls"] = True
        resp = self._request("POST", "/v1/sessions", opts)
        self.info = json.loads(resp.read())
        self.session_id = self.info["session_id"]
        self.last_seq = int(self.info.get("last_seq") or 0)

    def _request(self, method: str, path: str, body=None):
        headers = {"Content-Type": "application/json",
                   "User-Agent": "simple-harness-sdk-py"}
        if self.token:
            headers["Authorization"] = "Bearer " + self.token
        data = None if body is None else json.dumps(body).encode()
        req = urllib.request.Request(self.base + path, data=data,
                                     headers=headers, method=method)
        try:
            return urllib.request.urlopen(req)
        except urllib.error.HTTPError as e:
            detail = e.read().decode(errors="replace")[:256]
            raise RuntimeError(f"bridge {method} {path} → {e.code}: {detail}") from None

    def _stream(self, resp) -> Iterator[dict]:
        for line in resp:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            seq = ev.get("seq")
            if isinstance(seq, int) and seq > self.last_seq:
                self.last_seq = seq
            yield ev

    def _send(self, payload: dict, from_seq: Optional[int] = None) -> Iterator[dict]:
        """POST one protocol request; yield its streamed NDJSON events.
        from_seq replays persisted events with seq >= from_seq first."""
        query = "" if from_seq is None else f"?from={from_seq}"
        resp = self._request("POST", f"/v1/sessions/{self.session_id}{query}", payload)
        return self._stream(resp)

    def reconnect(self, from_seq: Optional[int] = None) -> Iterator[dict]:
        """Re-attach after losing the stream: replay persisted events with
        seq >= from_seq (default: everything after what this client saw), then
        follow live until the in-flight request's terminal event. Sends nothing
        to the model, so it is safe while a turn is running — including from a
        different process than the one that started it."""
        start = self.last_seq + 1 if from_seq is None else from_seq
        resp = self._request("GET", f"/v1/sessions/{self.session_id}/events?from={start}")
        return self._stream(resp)

    def chat(self, text: str, review: bool = False,
             from_seq: Optional[int] = None,
             images: Optional[List[ImageInput]] = None) -> Iterator[dict]:
        """Send a user turn; yield events until (and including) the 'turn'
        event. Raises RuntimeError if the stream ends without one (the
        session process died server-side)."""
        terminal = False
        payload = {"type": "review" if review else "user", "text": text}
        if images:
            payload["images"] = images
        for ev in self._send(payload, from_seq):
            yield ev
            if ev.get("type") in ("turn", "error"):
                terminal = True
                return
        if not terminal:
            raise RuntimeError("bridge stream ended mid-turn (session process died?)")

    def ask(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        """Run a turn and return just the final assistant text."""
        final = ""
        for ev in self.chat(text, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def review(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        """Run one isolated, read-only review turn and return its report."""
        final = ""
        for ev in self.chat(text, review=True, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def answer(self, text: str = "", cancelled: bool = False,
               call_id: Optional[str] = None) -> None:
        """Answer an in-flight ask_user event. The original chat stream
        continues and later yields the ask_user tool_result plus final turn."""
        req = {"type": "answer", "text": text, "cancelled": cancelled}
        if call_id:
            req["call_id"] = call_id
        self._request("POST", f"/v1/sessions/{self.session_id}", req).read()

    def set_system_prompt(self, text: str, append: bool = False) -> None:
        """Replace (or with append=True, extend) the system prompt for later
        turns. Same KV-cache warning as `Harness.set_system_prompt`: prefer
        the creation-time arguments; mutate only at task boundaries."""
        for ev in self._send({"type": "set_system_prompt", "text": text, "append": append}):
            if ev.get("type") == "error":
                raise RuntimeError(ev["message"])
            if ev.get("type") == "system_prompt":
                return
        raise RuntimeError("bridge stream ended before acking set_system_prompt")

    def append_system_prompt(self, text: str) -> None:
        """Tack extra instructions onto the current system prompt."""
        self.set_system_prompt(text, append=True)

    def score(self, prompt_or_sha: str, value: float, notes: str = "",
              parent: Optional[str] = None, judge_id: str = "",
              artifact_sha: str = "", eval_set_hash: str = "",
              niche: str = "", scale: str = "") -> None:
        """Record an evaluation score in the server-side trajectory archive —
        same semantics (and provenance fields) as `Harness.score`, including
        prompt-free MAP-Elites lineage and the optional `scale`
        ("unit" | "percent") override of the harness's value-normalization
        heuristic."""
        sha = prompt_or_sha if re.fullmatch(r"[0-9a-f]{16}", prompt_or_sha) \
            else prompt_fingerprint(prompt_or_sha)
        req = {"type": "score", "prompt_sha": sha, "score": value, "notes": notes}
        if parent is not None:
            req["parent_sha"] = parent if re.fullmatch(r"[0-9a-f]{16}", parent) \
                else prompt_fingerprint(parent)
        if judge_id:
            req["judge_id"] = judge_id
        if artifact_sha:
            req["artifact_sha"] = artifact_sha
        if eval_set_hash:
            req["eval_set_hash"] = eval_set_hash
        if niche:
            req["niche"] = niche
        if scale:
            req["scale"] = scale
        # The SDK emitter strips prompt_text until it has an interactive review UI.
        if niche and not re.fullmatch(r"[0-9a-f]{16}", prompt_or_sha):
            _fleet_signal("propose", {"niche": niche, "prompt_sha": sha,
                                      "parent_sha": req.get("parent_sha", ""),
                                      "prompt_text": prompt_or_sha})
        for ev in self._send(req):
            if ev.get("type") == "error":
                raise RuntimeError(ev["message"])
            if ev.get("type") == "score":
                return
        raise RuntimeError("bridge stream ended before acking score")

    def close(self):
        """Close the remote session (graceful: the bridge EOFs the child's
        stdin so it flushes telemetry/trajectory on the way out)."""
        try:
            self._request("DELETE", f"/v1/sessions/{self.session_id}").read()
        except (RuntimeError, OSError):
            pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()


# ── Serverless / In-Memory Agent Runtime (Stdlib-only, Lambda/Edge ready) ──

class InMemoryWorkspace:
    """In-memory virtual workspace for serverless / stateless Python agent runs.
    Supports `read_file`, `write_file`, `delete_file`, `list_files`, `snapshot`,
    `restore`, and `diff` without touching the host filesystem."""

    def __init__(self, initial_files: Optional[dict] = None, exec_fn=None):
        self._files: dict = {}
        for k, v in (initial_files or {}).items():
            self._files[self._norm(k)] = str(v)
        self.exec_fn = exec_fn

    @staticmethod
    def _norm(path: str) -> str:
        p = path.replace("\\", "/").lstrip("./")
        while p.startswith("/"):
            p = p[1:]
        return p.rstrip("/")

    def read_file(self, path: str) -> str:
        key = self._norm(path)
        if key not in self._files:
            raise FileNotFoundError(f"ENOENT: file not found: {path}")
        return self._files[key]

    def write_file(self, path: str, content: str) -> None:
        self._files[self._norm(path)] = str(content)

    def delete_file(self, path: str) -> None:
        key = self._norm(path)
        if key not in self._files:
            raise FileNotFoundError(f"ENOENT: file not found: {path}")
        del self._files[key]

    def list_files(self, prefix: str = "") -> List[str]:
        p = self._norm(prefix)
        return sorted(
            k for k in self._files.keys()
            if not p or k == p or k.startswith(p + "/")
        )

    def snapshot(self) -> dict:
        return {k: self._files[k] for k in sorted(self._files.keys())}

    def restore(self, files: dict) -> None:
        self._files.clear()
        for k, v in files.items():
            self._files[self._norm(k)] = str(v)

    def diff(self, baseline: Optional[dict] = None) -> List[dict]:
        base = {self._norm(k): str(v) for k, v in (baseline or {}).items()}
        keys = sorted(set(base.keys()) | set(self._files.keys()))
        out: List[dict] = []
        for k in keys:
            b = base.get(k)
            a = self._files.get(k)
            if b is None and a is not None:
                out.append({"path": k, "status": "added"})
            elif b is not None and a is None:
                out.append({"path": k, "status": "deleted"})
            elif b != a:
                out.append({"path": k, "status": "modified"})
        return out


def define_tool(name: str, description: str, parameters: dict, execute) -> dict:
    """Define a tool for `ServerlessHarness`."""
    return {
        "name": name,
        "description": description,
        "parameters": parameters,
        "execute": execute,
    }


def create_read_only_tools(workspace: InMemoryWorkspace) -> List[dict]:
    """Create read-only coding tools (`read_file`, `list_dir`, `grep`) backed by `workspace`."""
    def _read(inp: dict, _ctx: dict):
        content = workspace.read_file(str(inp.get("path", "")))
        lines = content.split("\n")
        start = max(1, int(inp.get("start_line") or 1))
        end = min(len(lines), int(inp.get("end_line") or len(lines)))
        return "\n".join(f"{start + i}: {line}" for i, line in enumerate(lines[start - 1:end]))

    def _list(inp: dict, _ctx: dict):
        files = workspace.list_files(str(inp.get("path", "")))
        return "\n".join(files) if files else "(empty)"

    def _grep(inp: dict, _ctx: dict):
        pattern = str(inp.get("pattern", ""))
        rx = re.compile(pattern)
        matches = []
        for f in workspace.list_files(str(inp.get("path", ""))):
            for idx, line in enumerate(workspace.read_file(f).split("\n"), 1):
                if rx.search(line):
                    matches.append(f"{f}:{idx}:{line}")
        return "\n".join(matches) if matches else "No matches found."

    return [
        define_tool(
            "read_file",
            "Read the contents of a file in the workspace.",
            {"type": "object", "properties": {"path": {"type": "string"}, "start_line": {"type": "integer"}, "end_line": {"type": "integer"}}, "required": ["path"]},
            _read,
        ),
        define_tool(
            "list_dir",
            "List files in the workspace under an optional prefix.",
            {"type": "object", "properties": {"path": {"type": "string"}}},
            _list,
        ),
        define_tool(
            "grep",
            "Search files in the workspace for a regex pattern.",
            {"type": "object", "properties": {"pattern": {"type": "string"}, "path": {"type": "string"}}, "required": ["pattern"]},
            _grep,
        ),
    ]


def create_coding_tools(workspace: InMemoryWorkspace) -> List[dict]:
    """Create coding tools (`read_file`, `write_file`, `edit_file`, `list_dir`, `grep`, and optional `bash`) backed by `workspace`."""
    tools = list(create_read_only_tools(workspace))

    def _write(inp: dict, _ctx: dict):
        path = str(inp.get("path", ""))
        content = str(inp.get("content", ""))
        workspace.write_file(path, content)
        return f"Wrote {len(content)} bytes to {path}"

    def _edit(inp: dict, _ctx: dict):
        path = str(inp.get("path", ""))
        old_s = str(inp.get("old_str", ""))
        new_s = str(inp.get("new_str", ""))
        replace_all = bool(inp.get("replace_all", False))
        if not old_s:
            return {"output": "old_str must not be empty", "is_error": True}
        content = workspace.read_file(path)
        count = content.count(old_s)
        if count == 0:
            return {"output": f"old_str not found in {path}", "is_error": True}
        if count > 1 and not replace_all:
            return {"output": f"old_str appears {count} times in {path}", "is_error": True}
        updated = content.replace(old_s, new_s) if replace_all else content.replace(old_s, new_s, 1)
        workspace.write_file(path, updated)
        return f"Updated {path}"

    tools.append(define_tool(
        "write_file",
        "Create or overwrite a file in the workspace.",
        {"type": "object", "properties": {"path": {"type": "string"}, "content": {"type": "string"}}, "required": ["path", "content"]},
        _write,
    ))
    tools.append(define_tool(
        "edit_file",
        "Replace an exact string in a file with a new string.",
        {"type": "object", "properties": {"path": {"type": "string"}, "old_str": {"type": "string"}, "new_str": {"type": "string"}, "replace_all": {"type": "boolean"}}, "required": ["path", "old_str", "new_str"]},
        _edit,
    ))
    if workspace.exec_fn is not None:
        def _bash(inp: dict, _ctx: dict):
            res = workspace.exec_fn(str(inp.get("command", "")))
            return {"output": res.get("output", ""), "is_error": res.get("exit_code", 0) != 0}
        tools.append(define_tool(
            "bash",
            "Execute a shell command in the workspace.",
            {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]},
            _bash,
        ))
    return tools


class ServerlessHarness:
    """Zero-binary, stdlib-only Python agent session for AWS Lambda, Cloud
    Functions, and in-memory testing. Emits the same event dicts as `Harness`
    and `RemoteHarness`."""

    def __init__(self, provider: str = "codegraff", model: str = "gpt-5.5",
                 api_key: Optional[str] = None, endpoint: Optional[str] = None,
                 system_prompt: Optional[str] = None,
                 append_system_prompt: Optional[str] = None,
                 workspace: Optional[Union[InMemoryWorkspace, dict]] = None,
                 coding_tools: Union[bool, str] = True,
                 tools: Optional[List[dict]] = None,
                 stream_fn=None, before_tool_call=None, after_tool_call=None,
                 transform_context=None, max_tool_calls: int = 32,
                 max_model_calls: int = 64, dedupe_tool_calls: bool = False,
                 session: Optional[dict] = None):
        if isinstance(workspace, InMemoryWorkspace):
            self.workspace = workspace
        else:
            self.workspace = InMemoryWorkspace(workspace if isinstance(workspace, dict) else {})
        if session and isinstance(session.get("files"), dict):
            self.workspace.restore(session["files"])
        self.session_id = (session or {}).get("session_id") or ("serverless-" + secrets.token_hex(4))
        self.provider = (session or {}).get("provider") or provider
        self.model = (session or {}).get("model") or model
        self.effort = (session or {}).get("effort") or "medium"
        self.base_system_prompt = (session or {}).get("system_prompt") or system_prompt or (
            "You are Graff, an autonomous coding agent. Use the provided tools to inspect, edit, and verify files before answering."
        )
        self.appended_system_prompt = append_system_prompt or ""
        self.last_seq = int((session or {}).get("seq") or 0)
        self.messages: List[dict] = list((session or {}).get("messages") or [])
        self.api_key = api_key
        self.endpoint = endpoint
        self.stream_fn = stream_fn
        self.before_tool_call = before_tool_call
        self.after_tool_call = after_tool_call
        self.transform_context = transform_context
        self.max_tool_calls = max_tool_calls
        self.max_model_calls = max_model_calls
        self.total_model_calls = 0
        self.dedupe_tool_calls = dedupe_tool_calls
        self._steer_queue: List[str] = []
        self._followup_queue: List[str] = []
        self._tool_map: dict = {}
        if coding_tools == "readonly":
            for t in create_read_only_tools(self.workspace):
                self._tool_map[t["name"]] = t
        elif coding_tools:
            for t in create_coding_tools(self.workspace):
                self._tool_map[t["name"]] = t
        for t in (tools or []):
            self._tool_map[t["name"]] = t

    def steer(self, text: str) -> None:
        if text.strip():
            self._steer_queue.append(text)

    def follow_up(self, text: str) -> None:
        if text.strip():
            self._followup_queue.append(text)

    def export_state(self) -> dict:
        return {
            "version": 1,
            "session_id": self.session_id,
            "provider": self.provider,
            "model": self.model,
            "effort": self.effort,
            "system_prompt": self._effective_system_prompt(),
            "seq": self.last_seq,
            "messages": json.loads(json.dumps(self.messages)),
            "files": self.workspace.snapshot(),
        }

    def import_state(self, snapshot: dict) -> None:
        self.provider = snapshot["provider"]
        self.model = snapshot["model"]
        self.effort = snapshot.get("effort", "medium")
        self.base_system_prompt = snapshot["system_prompt"]
        self.appended_system_prompt = ""
        self.last_seq = int(snapshot.get("seq", 0))
        self.messages = json.loads(json.dumps(snapshot.get("messages", [])))
        if isinstance(snapshot.get("files"), dict):
            self.workspace.restore(snapshot["files"])

    def _effective_system_prompt(self) -> str:
        if self.appended_system_prompt:
            return f"{self.base_system_prompt}\n\n{self.appended_system_prompt}"
        return self.base_system_prompt

    def _emit(self, payload: dict) -> dict:
        self.last_seq += 1
        return {"seq": self.last_seq, **payload}

    def chat(self, text: str, review: bool = False,
             images: Optional[List[ImageInput]] = None) -> Iterator[dict]:
        saved = json.loads(json.dumps(self.messages)) if review else None
        try:
            yield self._emit({"type": "started", "provider": self.provider, "model": self.model})
            user_msg: dict = {"role": "user", "content": text}
            if images:
                user_msg["images"] = images
            self.messages.append(user_msg)
            active_tools = create_read_only_tools(self.workspace) if review else list(self._tool_map.values())
            active_map = {t["name"]: t for t in active_tools}
            tool_calls_turn = 0
            api_calls_turn = 0
            in_tok = 0
            out_tok = 0
            final_text = ""
            seen_keys = set()

            while True:
                while self._steer_queue:
                    self.messages.append({"role": "user", "content": self._steer_queue.pop(0)})
                if self.total_model_calls >= self.max_model_calls:
                    yield self._emit({"type": "error", "message": f"max_model_calls ({self.max_model_calls}) exceeded"})
                    return
                ctx_msgs = self.transform_context(list(self.messages)) if self.transform_context else list(self.messages)
                self.total_model_calls += 1
                api_calls_turn += 1
                req_payload = {
                    "provider": self.provider,
                    "model": self.model,
                    "effort": self.effort,
                    "system_prompt": (
                        f"{self._effective_system_prompt()}\n\n[review mode: read-only inspection]"
                        if review else self._effective_system_prompt()
                    ),
                    "messages": ctx_msgs,
                    "tools": [{"name": t["name"], "description": t["description"], "parameters": t["parameters"]} for t in active_tools],
                }
                try:
                    resp = self.stream_fn(req_payload) if self.stream_fn is not None else self._call_http_provider(req_payload)
                except Exception as err:
                    yield self._emit({"type": "error", "message": str(err)})
                    return
                step_text = resp.get("text", "")
                in_tok += int(resp.get("input_tokens", 0))
                out_tok += int(resp.get("output_tokens", 0))
                if step_text:
                    final_text = step_text
                    yield self._emit({"type": "text", "text": step_text})
                calls = resp.get("tool_calls") or []
                self.messages.append({"role": "assistant", "content": step_text, "tool_calls": calls})
                if not calls:
                    if self._followup_queue:
                        self.messages.append({"role": "user", "content": self._followup_queue.pop(0)})
                        continue
                    break
                for call in calls:
                    name = call.get("name", "")
                    inp = call.get("input") or {}
                    cid = call.get("id", "call_1")
                    if tool_calls_turn >= self.max_tool_calls:
                        msg = f"max_tool_calls ({self.max_tool_calls}) exceeded"
                        yield self._emit({"type": "tool_rejected", "name": name, "reason": "budget", "input": inp, "message": msg})
                        yield self._emit({"type": "tool_result", "name": name, "is_error": True, "text": msg})
                        self.messages.append({"role": "tool", "tool_call_id": cid, "tool_name": name, "content": msg, "is_error": True})
                        continue
                    k = f"{name}:{json.dumps(inp, sort_keys=True)}"
                    if self.dedupe_tool_calls and k in seen_keys:
                        msg = f"duplicate tool call rejected: {name}"
                        yield self._emit({"type": "tool_rejected", "name": name, "reason": "duplicate", "input": inp, "message": msg})
                        yield self._emit({"type": "tool_result", "name": name, "is_error": True, "text": msg})
                        self.messages.append({"role": "tool", "tool_call_id": cid, "tool_name": name, "content": msg, "is_error": True})
                        continue
                    seen_keys.add(k)
                    if self.before_tool_call:
                        gate = self.before_tool_call({"call_id": cid, "name": name, "input": inp, "step": api_calls_turn})
                        if isinstance(gate, dict) and gate.get("block"):
                            msg = gate.get("reason") or f"blocked: {name}"
                            yield self._emit({"type": "tool_rejected", "name": name, "reason": "policy", "input": inp, "message": msg})
                            yield self._emit({"type": "tool_result", "name": name, "is_error": True, "text": msg})
                            self.messages.append({"role": "tool", "tool_call_id": cid, "tool_name": name, "content": msg, "is_error": True})
                            continue
                    tool = active_map.get(name)
                    if tool is None:
                        msg = f"unknown tool: {name}"
                        yield self._emit({"type": "tool_result", "name": name, "is_error": True, "text": msg})
                        self.messages.append({"role": "tool", "tool_call_id": cid, "tool_name": name, "content": msg, "is_error": True})
                        continue
                    tool_calls_turn += 1
                    yield self._emit({"type": "tool_call", "name": name, "input": inp})
                    try:
                        raw = tool["execute"](inp, {"call_id": cid, "workspace": self.workspace})
                        if isinstance(raw, dict):
                            out_s = str(raw.get("output", ""))
                            is_err = bool(raw.get("is_error", False))
                        else:
                            out_s = str(raw)
                            is_err = False
                    except Exception as e:
                        out_s = str(e)
                        is_err = True
                    if self.after_tool_call:
                        post = self.after_tool_call({"call_id": cid, "name": name, "input": inp, "output": out_s, "is_error": is_err})
                        if isinstance(post, dict):
                            out_s = str(post.get("output", out_s))
                            is_err = bool(post.get("is_error", is_err))
                    yield self._emit({"type": "tool_result", "name": name, "is_error": is_err, "text": out_s})
                    self.messages.append({"role": "tool", "tool_call_id": cid, "tool_name": name, "content": out_s, "is_error": is_err})
            yield self._emit({
                "type": "turn",
                "text": final_text,
                "context_tokens": in_tok + out_tok,
                "cost_usd": 0.0,
                "input_tokens": in_tok,
                "uncached_input_tokens": in_tok,
                "cache_read_tokens": 0,
                "output_tokens": out_tok,
                "api_calls": api_calls_turn,
                "subscription_calls": 0,
                "unpriced_calls": api_calls_turn,
                "complete": True,
                "metadata_complete": True,
            })
        finally:
            if saved is not None:
                self.messages = saved

    def ask(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        final = ""
        for ev in self.chat(text, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def review(self, text: str, images: Optional[List[ImageInput]] = None) -> str:
        final = ""
        for ev in self.chat(text, review=True, images=images):
            if ev.get("type") == "turn":
                final = ev["text"]
            elif ev.get("type") == "error":
                raise RuntimeError(ev["message"])
        return final

    def set_model(self, provider: str, model: str) -> None:
        if not provider or not model:
            raise ValueError("provider and model are required")
        self.provider = provider
        self.model = model

    def set_effort(self, level: str) -> None:
        self.effort = level

    def set_system_prompt(self, text: str, append: bool = False) -> None:
        if append:
            self.appended_system_prompt = (
                f"{self.appended_system_prompt}\n\n{text}" if self.appended_system_prompt else text
            )
        else:
            self.base_system_prompt = text
            self.appended_system_prompt = ""

    def append_system_prompt(self, text: str) -> None:
        self.set_system_prompt(text, append=True)

    def compact(self) -> None:
        if len(self.messages) <= 2:
            return
        keep_from = max(1, len(self.messages) - 2)
        older = self.messages[:keep_from]
        recent = self.messages[keep_from:]
        lines = [f"- [{m.get('role')}]: {str(m.get('content', ''))[:200]}" for m in older]
        handoff = {
            "role": "user",
            "content": f"[compacted session summary ({len(older)} earlier messages)]\n" + "\n".join(lines),
        }
        self.messages = [handoff, *recent]

    def _call_http_provider(self, req: dict) -> dict:
        if not self.api_key and not self.endpoint:
            raise RuntimeError("ServerlessHarness requires stream_fn, api_key, or endpoint")
        if self.provider == "anthropic":
            url = (self.endpoint or "https://api.anthropic.com/v1").rstrip("/")
            if not url.endswith("/messages"):
                url += "/messages"
            headers = {
                "Content-Type": "application/json",
                "anthropic-version": "2023-06-01",
            }
            if self.api_key:
                headers["x-api-key"] = self.api_key
            body = json.dumps({
                "model": req["model"],
                "max_tokens": 8192,
                "system": req["system_prompt"],
                "messages": [{"role": "user" if m["role"] == "tool" else m["role"], "content": m.get("content", "")} for m in req["messages"]],
                "tools": [{"name": t["name"], "description": t["description"], "input_schema": t["parameters"]} for t in req["tools"]],
            }).encode()
            http_req = urllib.request.Request(url, data=body, headers=headers, method="POST")
            data = json.loads(urllib.request.urlopen(http_req).read())
            text_parts = []
            tool_calls = []
            for b in data.get("content", []):
                if b.get("type") == "text":
                    text_parts.append(b.get("text", ""))
                elif b.get("type") == "tool_use":
                    tool_calls.append({"id": b.get("id", "call_1"), "name": b.get("name", ""), "input": b.get("input") or {}})
            usage = data.get("usage") or {}
            return {
                "text": "".join(text_parts),
                "tool_calls": tool_calls,
                "input_tokens": int(usage.get("input_tokens", 0)),
                "output_tokens": int(usage.get("output_tokens", 0)),
            }
        url = (self.endpoint or "https://api.openai.com/v1").rstrip("/")
        if not url.endswith("/chat/completions"):
            url += "/chat/completions"
        headers = {"Content-Type": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        oai_msgs = [{"role": "system", "content": req["system_prompt"]}]
        for m in req["messages"]:
            if m["role"] == "assistant" and m.get("tool_calls"):
                oai_msgs.append({
                    "role": "assistant",
                    "content": m.get("content") or None,
                    "tool_calls": [
                        {"id": tc.get("id", "call_1"), "type": "function", "function": {"name": tc.get("name", ""), "arguments": json.dumps(tc.get("input") or {})}}
                        for tc in m["tool_calls"]
                    ],
                })
            elif m["role"] == "tool":
                oai_msgs.append({
                    "role": "tool",
                    "tool_call_id": m.get("tool_call_id", "call_1"),
                    "content": m.get("content", ""),
                })
            else:
                oai_msgs.append({"role": m["role"], "content": m.get("content", "")})
        body = json.dumps({
            "model": req["model"],
            "messages": oai_msgs,
            "tools": [{"type": "function", "function": t} for t in req["tools"]] if req["tools"] else None,
        }).encode()
        http_req = urllib.request.Request(url, data=body, headers=headers, method="POST")
        data = json.loads(urllib.request.urlopen(http_req).read())
        choice = (data.get("choices") or [{}])[0].get("message") or {}
        tool_calls = []
        for idx, tc in enumerate(choice.get("tool_calls") or []):
            fn = tc.get("function") or {}
            raw_args = fn.get("arguments") or "{}"
            try:
                parsed = json.loads(raw_args) if isinstance(raw_args, str) else raw_args
            except Exception:
                parsed = {}
            tool_calls.append({"id": tc.get("id", f"call_{idx+1}"), "name": fn.get("name", ""), "input": parsed})
        usage = data.get("usage") or {}
        return {
            "text": choice.get("content") or "",
            "tool_calls": tool_calls,
            "input_tokens": int(usage.get("prompt_tokens", 0)),
            "output_tokens": int(usage.get("completion_tokens", 0)),
        }

    def close(self) -> None:
        pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()


def create_agent_session(**kwargs) -> dict:
    """Create a serverless Python agent session (`{"harness": h, "workspace": h.workspace}`)."""
    h = ServerlessHarness(**kwargs)
    return {"harness": h, "workspace": h.workspace}


def run_agent_serverless(prompt: str, **kwargs) -> Iterator[dict]:
    """Run a single serverless turn, yielding event dicts."""
    with ServerlessHarness(**kwargs) as h:
        yield from h.chat(prompt)
